use super::*;
use serde_json::json;
use crate::local_database::attachment_download_owner::native_archive_capture::tests::{installed,archive_owner,local};
use std::fs;
use std::os::unix::fs::{PermissionsExt,DirBuilderExt};
async fn fixture()->(PathBuf,Value,String){let work=std::env::temp_dir().join(format!("starlane-archive-adapter-{}",std::process::id()));let work=work.join(format!("fixture-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&work).unwrap();fs::set_permissions(&work,fs::Permissions::from_mode(0o700)).unwrap();let root=work.join("vault");fs::create_dir(&root).unwrap();installed(&root).await;let parent=work.join("out");fs::create_dir(&parent).unwrap();let owner=archive_owner(&root).await;let binding=std::sync::Arc::new(std::sync::Mutex::new(Value::Null));let saved=binding.clone();let output=parent.join("original.zip");assert!(owner.with_capture(local(),move|capture|{let b=capture.output_binding();*saved.lock().unwrap()=b.clone();let selected=native_archive_output::test_selection(output,b.clone())?;native_archive_output::test_compose_interrupted(capture,selected,||Ok(b.clone()))}).await.is_err());let binding=binding.lock().unwrap().clone();let db=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();let raw:String=sqlx::query_scalar("SELECT receipt FROM native_attachment_download_receipts").fetch_one(&db).await.unwrap();db.close().await;(work,binding,raw)}
fn caller_at(work:&std::path::Path,binding:Value,current:&Value)->Result<Caller,String>{let root=work.join("vault");let selection=vault::SnapshotRequestBinding::capture_at(work.join("settings.json"),root,"none")?;Caller::capture(selection,"none",binding,work.join("out"),current)}
#[tokio::test]async fn current_native_vault_context_lists_and_reviews_without_rebinding_historical_revision(){let(work,binding,raw)=fixture().await;let db=sqlx::sqlite::SqlitePoolOptions::new().connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(work.join("vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();sqlx::query("UPDATE local_vault_metadata SET value='newer-current' WHERE key='canonical_revision'").execute(&db).await.unwrap();db.close().await;let rows=caller_at(&work,binding.clone(),&local()).unwrap().list(local()).await.unwrap();let report=rows["inventory"]["operations"][0].clone();let op=report["operation"].as_str().unwrap().to_owned();let result=caller_at(&work,binding,&local()).unwrap().review(local(),op,report).await.unwrap();assert_eq!(result["retry_authority"],false);assert_eq!(result["serve_authority"],false);assert!(!work.join("out/original.zip").exists());let db=sqlx::sqlite::SqlitePoolOptions::new().connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(work.join("vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();let after:String=sqlx::query_scalar("SELECT receipt FROM native_attachment_download_receipts").fetch_one(&db).await.unwrap();assert_eq!(after,raw);db.close().await;fs::remove_dir_all(work).unwrap();}
#[tokio::test]async fn changed_context_provider_root_or_settings_refuses_before_review(){for mode in["context","provider","root","settings","database"]{let(work,mut binding,_)=fixture().await;let mut current=local();if mode=="context"{current["sessionId"]=json!("foreign");}if mode=="provider"{binding["context"]["provider"]=json!("google-drive");}if mode=="root"{binding["root"]=json!("/foreign-vault");}if mode=="settings"||mode=="database"{let held=caller_at(&work,binding,&current).unwrap();if mode=="settings"{fs::write(work.join("settings.json"),serde_json::to_vec(&json!({"vault_path":work.join("foreign")})).unwrap()).unwrap();}else{let root=work.join("vault");fs::rename(root.join(".starlane"),root.join(".starlane-held")).unwrap();fs::create_dir(root.join(".starlane")).unwrap();fs::rename(root.join(".starlane-held/starlane-notes.sqlite3"),root.join(".starlane/starlane-notes.sqlite3")).unwrap();}assert!(held.list(current).await.is_err());}else{assert!(caller_at(&work,binding,&current).is_err());}assert!(fs::read_dir(work.join("out")).unwrap().all(|e|!e.unwrap().path().join("review.json").exists()));fs::remove_dir_all(work).unwrap();}}
#[tokio::test]async fn native_guard_runs_immediately_before_durable_review(){let(work,binding,_)=fixture().await;let rows=native_archive_output::pending(&work.join("out"),&binding).unwrap();let report=rows["operations"][0].clone();let op=report["operation"].as_str().unwrap();let checks=std::cell::Cell::new(0);let result=native_archive_output::recovery::acknowledge_review_guarded(&work.join("out"),op,&binding,&report,||{checks.set(checks.get()+1);if checks.get()==2{Err("current app selection changed before write".into())}else{Ok(())}});assert!(result.is_err());assert!(!work.join(format!("out/.starlane-archive-{op}/review.json")).exists());fs::remove_dir_all(work).unwrap();}
#[tokio::test(flavor="multi_thread",worker_threads=2)]#[ignore="fresh-process actual IPC adapter worker invoked by parent"]async fn actual_fresh_ipc_review_worker(){let work=PathBuf::from(std::env::var("STARLANE_ARCHIVE_REVIEW_FIXTURE").expect("owned private fixture required"));let input:Value=serde_json::from_slice(&fs::read(work.join("adapter-input.json")).unwrap()).unwrap();let binding=&input["binding"];let root=work.join("vault");let app=tauri::test::mock_builder().plugin(tauri_plugin_store::Builder::new().build()).invoke_handler(tauri::generate_handler![list_native_vault_archive_export_outcomes,acknowledge_native_vault_archive_export_review]).build(tauri::test::mock_context(tauri::test::noop_assets())).unwrap();let settings=tauri_plugin_store::resolve_store_path(app.handle(),"settings.json").unwrap();assert!(settings.starts_with(&work));fs::create_dir_all(settings.parent().unwrap()).unwrap();fs::write(&settings,serde_json::to_vec(&json!({"vault_path":root})).unwrap()).unwrap();let window=tauri::WebviewWindowBuilder::new(&app,"review-worker",Default::default()).build().unwrap();let invoke=|command:&str,args:Value|tauri::test::get_ipc_response(&window,tauri::webview::InvokeRequest{cmd:command.into(),callback:tauri::ipc::CallbackFn(0),error:tauri::ipc::CallbackFn(1),url:"http://tauri.localhost".parse().unwrap(),body:tauri::ipc::InvokeBody::Json(args),headers:Default::default(),invoke_key:tauri::test::INVOKE_KEY.into()});let args=json!({"provider":"none","originalBinding":binding,"parentPath":work.join("out"),"current":binding["context"]});let response:Value=invoke("list_native_vault_archive_export_outcomes",args.clone()).unwrap().deserialize().unwrap();let report=response["inventory"]["operations"][0].clone();assert_eq!(report,input["report"]);let mut review=args;review["operation"]=report["operation"].clone();review["originalReport"]=report;let ack:Value=invoke("acknowledge_native_vault_archive_export_review",review).unwrap().deserialize().unwrap();assert_eq!(ack["result"]["reviewed"],true);assert_eq!(ack["retry_authority"],false);assert_eq!(ack["cleanup_authority"],false);assert_eq!(ack["serve_authority"],false);assert!(!work.join("out/original.zip").exists());println!("ACTUAL_FRESH_TAURI_IPC_ARCHIVE_REVIEW_NO_EXPORT_NO_UNLINK_PASS");}
#[tokio::test(flavor="multi_thread",worker_threads=2)]async fn actual_fresh_process_tauri_review_adapter_preserves_receipt_and_retained_stage(){let(work,binding,raw)=fixture().await;let rows=native_archive_output::pending(&work.join("out"),&binding).unwrap();fs::write(work.join("adapter-input.json"),serde_json::to_vec(&json!({"binding":binding,"report":rows["operations"][0]})).unwrap()).unwrap();let mut child=std::process::Command::new(std::env::current_exe().unwrap());child.args(["local_database::attachment_download_owner::native_archive_review::tests::actual_fresh_ipc_review_worker","--exact","--ignored","--nocapture"]).env("STARLANE_ARCHIVE_REVIEW_FIXTURE",&work);for(key,name)in[("XDG_CONFIG_HOME","config"),("XDG_DATA_HOME","data"),("XDG_CACHE_HOME","cache"),("XDG_STATE_HOME","state")]{let path=work.join(name);fs::DirBuilder::new().mode(0o700).create(&path).unwrap();child.env(key,path);}let result=child.output().unwrap();assert!(result.status.success(),"stdout:{} stderr:{}",String::from_utf8_lossy(&result.stdout),String::from_utf8_lossy(&result.stderr));assert!(String::from_utf8_lossy(&result.stdout).contains("ACTUAL_FRESH_TAURI_IPC_ARCHIVE_REVIEW_NO_EXPORT_NO_UNLINK_PASS"));let rows=native_archive_output::pending(&work.join("out"),&binding).unwrap();assert_eq!(rows["operations"][0]["reviewed"],true);let op=rows["operations"][0]["operation"].as_str().unwrap();assert!(work.join(format!("out/.starlane-archive-{op}/archive.zip")).exists());let db=sqlx::sqlite::SqlitePoolOptions::new().connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(work.join("vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();let after:String=sqlx::query_scalar("SELECT receipt FROM native_attachment_download_receipts").fetch_one(&db).await.unwrap();assert_eq!(after,raw);db.close().await;fs::remove_dir_all(work).unwrap();}
